template.script:
document.addEventListener('DOMContentLoaded', function () {
  var buttons = document.querySelectorAll('#wrap .hc-back-to-top');
  if (!buttons.length) return;
  var toggle = function () {
    var show = window.scrollY > 400;
    buttons.forEach(function (btn) { btn.classList.toggle('is-visible', show); });
  };
  window.addEventListener('scroll', toggle, { passive: true });
  toggle();
  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });
});

document.addEventListener('DOMContentLoaded', function () {
  var revealEls = document.querySelectorAll('#wrap .reveal');
  if (!revealEls.length) return;
  if ('IntersectionObserver' in window) {
    var obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12 });
    revealEls.forEach(function (el) { obs.observe(el); });
  } else {
    revealEls.forEach(function (el) { el.classList.add('is-visible'); });
  }
});

div.script:
document.addEventListener('DOMContentLoaded', function () {
  // Botón "Agregar al carrito" de arriba (al lado de WhatsApp):
  // solo despliega el formulario de tamaño/cantidad, no agrega
  // nada todavía — el agregado real pasa al enviar el form
  // ("Confirmar"), más abajo.
  var toggle = document.getElementById('add-to-cart-toggle');
  var bloque = document.getElementById('add-to-cart-block');
  if (toggle && bloque) {
    toggle.addEventListener('click', function () {
      var abierto = bloque.style.display !== 'none';
      bloque.style.display = abierto ? 'none' : 'block';
      if (!abierto) {
        bloque.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        var primerCampo = bloque.querySelector('select, input');
        if (primerCampo) primerCampo.focus();
      }
    });
  }

  var form = document.getElementById('add-to-cart-form');
  if (!form) return;
  var msg = document.getElementById('add-to-cart-msg');
  var select = form.querySelector('select[name="variante"]');

  // "Cancelar": cierra el formulario sin agregar nada y lo deja
  // limpio para la próxima vez (mismo criterio que si nunca se
  // hubiera abierto) -- sin esto, la única forma de cerrarlo era
  // volver a scrollear arriba y tocar "Agregar al carrito" de
  // nuevo, nada obvio una vez que ya se está mirando el
  // formulario abierto.
  var cancelar = document.getElementById('add-to-cart-cancel');
  if (cancelar && bloque) {
    cancelar.addEventListener('click', function () {
      form.reset();
      if (msg) msg.style.display = 'none';
      bloque.style.display = 'none';
    });
  }

  function mostrarMensaje(texto, ok) {
    if (!msg) return;
    msg.textContent = texto;
    msg.style.color = ok ? '#2f7d33' : '#9c2b1f';
    msg.style.display = '';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var productId = select ? (select.selectedOptions[0] && select.selectedOptions[0].getAttribute('data-product-id')) : form.getAttribute('data-product-id');
    var tmplId = select ? (select.selectedOptions[0] && select.selectedOptions[0].getAttribute('data-tmpl-id')) : form.getAttribute('data-tmpl-id');
    if (!productId || !tmplId) {
      mostrarMensaje('Elegí un tamaño antes de agregar al carrito.', false);
      return;
    }
    var cantidadInput = form.querySelector('input[name="cantidad"]');
    var cantidad = parseInt(cantidadInput ? cantidadInput.value : '1', 10);
    if (!cantidad || cantidad < 1) cantidad = 1;

    var boton = form.querySelector('button[type="submit"]');
    if (boton) boton.disabled = true;

    fetch('/shop/cart/add', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          product_template_id: parseInt(tmplId, 10),
          product_id: parseInt(productId, 10),
          quantity: cantidad,
        },
      }),
    })
      .then(function (r) { return r.json(); })
      .then(function (data) {
        if (boton) boton.disabled = false;
        if (!data || data.error || !data.result) {
          mostrarMensaje('No pudimos agregarlo al carrito. Probá de nuevo.', false);
          return;
        }
        mostrarMensaje('Agregado al carrito.', true);
        // El numerito del carrito cuenta PEDIDOS (líneas), no
        // unidades — data.result.cart_quantity es la suma de
        // cantidades, no sirve acá. Se pide aparte la cantidad
        // de líneas real.
        return fetch('/mi-sitio/carrito/lineas');
      })
      .then(function (r) { return r && r.json(); })
      .then(function (data) {
        if (!data) return;
        var badge = document.querySelector('.hc-cart-badge');
        if (badge) {
          badge.textContent = data.cantidad;
          badge.style.display = data.cantidad ? '' : 'none';
        }
      })
      .catch(function () {
        if (boton) boton.disabled = false;
        mostrarMensaje('No pudimos agregarlo al carrito. Probá de nuevo.', false);
      });
  });
});

(function () {
  var root = document.querySelector('.historia-page');
  if (!root) return;

  var toggle = document.getElementById('historia-theme-toggle');
  if (toggle) {
    var saved = null;
    try { saved = localStorage.getItem('historia-theme'); } catch (e) {}
    if (saved === 'dark') {
      root.setAttribute('data-theme', 'dark');
      toggle.textContent = '☀️';
    }
    toggle.addEventListener('click', function () {
      var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      toggle.textContent = next === 'dark' ? '☀️' : '🌙';
      try { localStorage.setItem('historia-theme', next); } catch (e) {}
    });
  }

  // Contadores animados de las stats (+40, +500, +150, 6): cuentan
  // desde 0 hasta el valor real la primera vez que entran en pantalla.
  var statEls = root.querySelectorAll('.historia-stat-value');
  if (statEls.length && 'IntersectionObserver' in window) {
    var animateCount = function (el) {
      var target = el.getAttribute('data-target') || '';
      var match = target.match(/^(\D*)(\d+)(\D*)$/);
      if (!match) return; // sin dígitos, se deja el texto tal cual
      var prefix = match[1], endNum = parseInt(match[2], 10), suffix = match[3];
      var duration = 1200, startTime = null;
      var step = function (timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / duration, 1);
        el.textContent = prefix + Math.floor(progress * endNum) + suffix;
        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = target; // valor final exacto, sin redondeos
        }
      };
      window.requestAnimationFrame(step);
    };
    var statsObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          animateCount(entry.target);
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.4 });
    statEls.forEach(function (el) { statsObserver.observe(el); });
  }
})();
